// Velociraptor docs: Pagefind search modal wired to Hextra's search inputs.
// The modal markup lives in layouts/_partials/search-modal.html; results are
// rendered by the Pagefind UI into #pagefind-ui. Pagefind assets are
// generated by `make pagefind` (bunx pagefind --site public) at build time.
(function () {
  "use strict";

  var searchInputs = document.querySelectorAll(".hextra-search-input");
  var wrapper = document.getElementById("search-wrapper");
  var modal = document.getElementById("search-modal");

  var searchVisible = false;
  var previouslyFocused = null;
  var pagefindUI = null;
  var pagefindLoaded = false;

  function loadPagefind() {
    if (pagefindLoaded) {
      return Promise.resolve();
    }
    pagefindLoaded = true;
    return new Promise(function (resolve, reject) {
      var css = document.createElement("link");
      css.rel = "stylesheet";
      css.href = "/pagefind/pagefind-ui.css";
      document.head.appendChild(css);

      var script = document.createElement("script");
      script.src = "/pagefind/pagefind-ui.js";
      script.onload = resolve;
      script.onerror = function () {
        pagefindLoaded = false;
        reject(new Error("pagefind-ui.js failed to load"));
      };
      document.head.appendChild(script);
    });
  }

  function displaySearch() {
    if (searchVisible) {
      return;
    }
    searchVisible = true;
    previouslyFocused = document.activeElement;
    wrapper.classList.remove("hx:invisible");
    loadPagefind()
      .then(function () {
        if (!pagefindUI) {
          pagefindUI = new PagefindUI({
            element: "#pagefind-ui",
            showSubResults: true,
            showImages: false,
            // "" disables the highlight param. With it set (default is "q")
            // Pagefind appends "?q=<query>" to every result link so terms
            // can be highlighted on the destination page. That pollutes the
            // URLs users share/bookmark, so we keep the links clean.
            highlightParam: ""
          });
        }
        var input = document.querySelector("#pagefind-ui input");
        if (input) {
          setTimeout(function () {
            input.focus();
          }, 60);
        }
      })
      .catch(function () {});
  }

  function hideSearch() {
    if (!searchVisible) {
      return;
    }
    // Restore focus BEFORE searchVisible flips to false. If the focus
    // target is one of our search inputs, its focus handler calls
    // displaySearch(), which early-returns while searchVisible is still
    // true - preventing the modal from instantly reopening. (Without
    // this reordering, closing after typing left the navbar input
    // focused, which fired displaySearch and re-opened the modal.)
    if (previouslyFocused && previouslyFocused.focus) {
      try {
        previouslyFocused.focus();
      } catch (e) {
        // The element may have been removed from the DOM; ignore.
      }
    }
    searchVisible = false;
    wrapper.classList.add("hx:invisible");
  }

  searchInputs.forEach(function (input) {
    input.addEventListener("click", displaySearch);
    input.addEventListener("focus", displaySearch);
  });

  if (wrapper) {
    wrapper.addEventListener("click", hideSearch);
  }
  if (modal) {
    modal.addEventListener("click", function (event) {
      event.stopPropagation();
      event.stopImmediatePropagation();
      return false;
    });
  }

  document.addEventListener("keydown", function (event) {
    // Forward slash opens search unless we are already typing somewhere.
    if (event.key === "/") {
      var active = document.activeElement;
      var tag = active ? active.tagName : null;
      var isInputField =
        tag === "INPUT" ||
        tag === "TEXTAREA" ||
        (active && active.isContentEditable);

      if (!searchVisible && !isInputField) {
        event.preventDefault();
        displaySearch();
      }
    }

    // Cmd+K (macOS) / Ctrl+K toggles the search modal.
    if (
      (event.key && event.key.toLowerCase() === "k") &&
      (event.metaKey || event.ctrlKey)
    ) {
      event.preventDefault();
      if (searchVisible) {
        hideSearch();
      } else {
        displaySearch();
      }
    }

    // Esc closes the search modal.
    if (event.key === "Escape") {
      hideSearch();
    }
  });

  // --- Section breadcrumb decorator ---
  // Derives a human-readable section path from each result URL and injects it
  // into the result card.  Works for both the modal (#pagefind-ui) and the
  // dedicated /search/ page (#pagefind-site-search).  A MutationObserver
  // re-enriches results every time the Pagefind UI re-renders them.

  var SECTION_NAMES = {
    docs:                "Documentation",
    vql_reference:       "VQL Reference",
    artifact_references: "Artifact Reference",
    exchange:            "Exchange",
    knowledge_base:      "Knowledge Base",
    blog:                "Blog",
    training:            "Training",
    announcements:       "Announcements",
    presentations:       "Presentations",
    downloads:           "Downloads",
    dev:                 "Developer",
    golang:              "Golang",
    vql:                 "VQL",
    gui:                 "Admin GUI",
    collection_policies: "Collection Policies",
    server:              "Server",
    windows:             "Windows",
    linux:               "Linux",
    macos:               "macOS",
    troubleshooting:     "Troubleshooting",
    pages:               "Pages",
  };

  // Every rendered page path (built at site-build time by
  // _partials/section-breadcrumb-paths.html).  Lazy-read because this
  // script is deferred; the JSON script tag sits later in the DOM.  The
  // breadcrumb decorator links a segment only when its path exists here,
  // so segments for missing intermediate levels (e.g. /blog/2024) render
  // as plain text instead of a dead link.
  var sitePagePaths = null;
  function getSitePagePaths() {
    if (sitePagePaths === null) {
      var el = document.getElementById("site-section-paths");
      sitePagePaths = new Set();
      if (el) {
        try {
          var raw = JSON.parse(el.textContent || el.innerText || "[]");
          (raw || []).forEach(function (p) { sitePagePaths.add(p); });
        } catch (e) { sitePagePaths = new Set(); }
      }
    }
    return sitePagePaths;
  }

  // Existing /tags/<slug>/ pages, from the section-tag-slugs partial
  // (ground truth = the taxonomy itself).  Tag pills in search results and
  // content pages hyperlink to the tag page ONLY when it actually exists,
  // so we never emit a dead tag link.
  var tagSlugSet = null;
  function getTagSlugSet() {
    if (tagSlugSet) return tagSlugSet;
    var el = document.getElementById("section-tag-slugs");
    if (!el) return new Set(); // partial not rendered yet; retry next call
    try {
      var raw = JSON.parse(el.textContent || el.innerText || "[]");
      tagSlugSet = new Set(raw || []);
    } catch (e) {
      tagSlugSet = new Set();
    }
    return tagSlugSet;
  }
  function slugifyTag(value) {
    return value.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
  }
  function tagUrlFor(value) {
    return getTagSlugSet().has("/tags/" + slugifyTag(value) + "/")
      ? "/tags/" + slugifyTag(value) + "/"
      : null;
  }

  function titleCase(str) {
    return str
      .replace(/[-_]/g, " ")
      .replace(/\b\w/g, function (c) { return c.toUpperCase(); });
  }

  function segmentName(str) {
    return SECTION_NAMES[str] || titleCase(str);
  }

  function deriveBreadCrumb(href) {
    try {
      var u = new URL(href, location.origin);
      var parts = u.pathname.split("/").filter(Boolean);
      if (parts.length < 2) return "";
      var paths = getSitePagePaths();
      var segments = [];
      var path = "";
      for (var i = 0; i < parts.length - 1; i++) {
        path += "/" + parts[i];
        var name = segmentName(parts[i]);
        if (paths.has(path)) {
          segments.push("<a href=\"" + path + "/\">" + name + "</a>");
        } else {
          // No real page at this level -> plain (non-hyperlink) segment.
          segments.push("<span class=\"pagefind-ui__breadcrumb-seg\">" + name + "</span>");
        }
      }
      return segments.join(" <span class=\"pagefind-ui__breadcrumb-sep\">\u203a</span> ");
    } catch (e) {
      return "";
    }
  }

  // Normalize PagefindUI tag chips.  Custom meta is morphed by PagefindUI
  // into one chip per meta key ("Tags: Client Artifact, Server Artifact"),
  // but we supply the tags as a comma-separated meta value from the page
  // frontmatter (mirrored onto <body data-pagefind-meta="tags: ...">).
  // Split that single chip into one pill per tag.  The "Tags: " prefix is
  // dropped so each chip shows the bare tag value.
  function normalizeTagChips(result) {
    result.querySelectorAll(
      '.pagefind-ui__result-tag[data-pagefind-ui-meta="tags"]'
    ).forEach(function (li) {
      var text = li.textContent || "";
      var prefix = text.match(/^[^:]*:\s*/);
      var value = prefix ? text.slice(prefix[0].length) : text;
      var values = value
        .split(/[,;]/)
        .map(function (s) { return s.trim(); })
        .filter(Boolean);
      if (!values.length) return;
      var parent = li.parentNode;
      var before = li.nextSibling;
      values.forEach(function (v) {
        var item = document.createElement("li");
        item.className =
          "pagefind-ui__result-tag pagefind-ui__result-tag--single";
        // Tags are normalized to lowercase everywhere, so display the
        // chip text lowercased too (the taxonomy slugs are lowercased).
        v = v.toLowerCase();
        // Result chips elsewhere link to the tag page when one exists
        // (the /search/ page's Tags accordion is the one place a chip
        // filters instead of linking).
        var url = tagUrlFor(v);
        if (url) {
          var a = document.createElement("a");
          a.href = url;
          a.className = "pagefind-ui__result-tag-link";
          a.textContent = v;
          item.appendChild(a);
        } else {
          item.textContent = v;
        }
        parent.insertBefore(item, before);
      });
      parent.removeChild(li);
    });
  }

  // Content-page tag paragraphs: several knowledge-base / exchange pages end
  // with a plain markdown line like "Tags: #debugging #vql".  Exchange
  // artifact descriptions instead close with a bare line that is entirely
  // hashtags ("#sigma #hayabusa #evtx"), either as its own paragraph or as
  // the final line of the last description paragraph.  Turn all of these
  // into the same pill badges used on search results.  Tags are lowercased
  // and only valid tags (>= 2 chars, containing at least one alphabetic
  // character) become pills; anything else (e.g. a bare "#0") is left as
  // plain text.
  function decorateTagParagraphs(root) {
    root.querySelectorAll(".content p").forEach(function (p) {
      if (p.dataset.tagsDecorated) return;
      var text = p.textContent.trim();
      var embedded = false;
      var m = text.match(/^Tags?:\s*(.*)$/i);
      if (!m && /^(?:#\S+\s*)+$/.test(text)) {
        // A paragraph that consists entirely of hashtags.
        m = [text, text];
      } else if (!m) {
        // A paragraph whose final line is solely hashtags (trailing tag
        // line in an exchange description).  Keep the surrounding prose,
        // turn only the tag line into pills.
        var lines = text.split("\n");
        var last = lines.length > 1 ? lines[lines.length - 1].trim() : "";
        if (/^#\S+(\s+#\S+)*$/.test(last)) {
          embedded = true;
          p.textContent = lines.slice(0, -1).join("\n");
          m = [last, last];
        }
      }
      if (!m) return;
      var values = m[1]
        .split(/[,;]+|\s+/)
        .map(function (s) { return s.trim().replace(/^#/, ""); })
        .filter(Boolean);
      if (!values.length) return;
      p.dataset.tagsDecorated = "true";
      if (embedded) {
        // Trailing tags in an exchange description: keep the prose prefix,
        // append the tag pills inline at the end of the paragraph (spaced
        // via .tags-badges-inline, see custom.css).
        var wrap = document.createElement("span");
        wrap.className = "tags-badges-inline";
        appendTagPills(wrap, values);
        p.appendChild(wrap);
        return;
      }
      p.classList.add("tags-badges");
      p.textContent = "";
      appendTagPills(p, values);
    });
  }

  // Build the pill DOM for one value and append it to the paragraph.
  // Invalid tags (shorter than 2 chars / no alphabetic character) stay as
  // plain "#text" spans; valid tags become green .tag-badge pills that
  // hyperlink to their /tags/ page only when that page actually exists.
  function appendTagPills(p, values) {
    values.forEach(function (v) {
      if (v.length < 2 || !/[a-z]/i.test(v)) {
        var span = document.createElement("span");
        span.textContent = "#" + v;
        p.appendChild(span);
        return;
      }
      v = v.toLowerCase();
      var url = tagUrlFor(v);
      var badge = document.createElement(url ? "a" : "span");
      badge.className = "tag-badge" + (url ? " tag-badge--link" : "");
      badge.textContent = v;
      if (url) badge.href = url;
      p.appendChild(badge);
    });
  }

  function decoratePagefindResults(container) {
    // Belt-and-suspenders: normalize every result link (top-level AND nested)
    // so no query string survives, regardless of Pagefind bundle behaviour.
    // Pagefind's default UI only appends the query when highlightParam is set,
    // but this guard also covers nested sub-result links and future bundles.
    container
      .querySelectorAll("a.pagefind-ui__result-link")
      .forEach(function (link) {
        var href = link.getAttribute("href");
        if (!href || href.indexOf("?") === -1) return;
        try {
          var u = new URL(href, location.origin);
          u.search = "";
          link.setAttribute("href", u.pathname + u.hash);
        } catch (e) {}
      });

    container.querySelectorAll(".pagefind-ui__result").forEach(function (result) {
      if (result.closest(".pagefind-ui__result-nested")) return;
      var link = result.querySelector(".pagefind-ui__result-link");
      if (!link) return;

      // Breadcrumb (one per top-level result), inserted just below the
      // title so the card reads: title > breadcrumb > excerpt > tags.
      if (!result.querySelector(".pagefind-ui__breadcrumb")) {
        var path = deriveBreadCrumb(link.getAttribute("href"));
        if (path) {
          var div = document.createElement("div");
          div.className = "pagefind-ui__breadcrumb";
          div.innerHTML = path;
          var inner = result.querySelector(".pagefind-ui__result-inner");
          if (inner) {
            var title = result.querySelector(".pagefind-ui__result-title");
            if (title && title.nextSibling) {
              inner.insertBefore(div, title.nextSibling);
            } else {
              inner.appendChild(div);
            }
          }
        }
      }

      // Tag chips (split the meta chip into per-tag pills).
      normalizeTagChips(result);
    });
  }

  function observePagefindResults(container) {
    decoratePagefindResults(container);
    new MutationObserver(function () {
      decoratePagefindResults(container);
      maintainTagFilters();
      positionSiteTagsPanel();
    }).observe(container, { childList: true, subtree: true });
  }

  // Tag-filter maintenance (the /search/ page only).  Native PagefindUI
  // renders a "tags" filter block in the drawer once tags are indexed; we
  // hide it (our custom Tags accordion serves the same purpose) and then
  // keep the accordion pill states in sync with the underlying checkbox.
  function maintainTagFilters() {
    if (!document.querySelector(".search-box[data-site-search]")) return;
    hideNativeTagFilters();
    syncTagPills();
  }

  function tagFilterCheckbox(tag) {
    var box = document.querySelector(".search-box[data-site-search]");
    if (!box) return null;
    return box.querySelector('input[name="tags"][value="' + CSS.escape(tag) + '"]');
  }

  function hideNativeTagFilters() {
    var box = document.querySelector(".search-box[data-site-search]");
    if (!box) return;
    box.querySelectorAll("details.pagefind-ui__filter-block").forEach(function (block) {
      if (block.querySelector('input[name="tags"]')) {
        block.hidden = true;
      }
    });
  }

  function syncTagPills() {
    document.querySelectorAll("#pagefind-site-tags .search-tag-link").forEach(function (pill) {
      var cb = tagFilterCheckbox(pill.dataset.tag);
      var active = !!(cb && cb.checked);
      pill.classList.toggle("is-active", active);
      pill.setAttribute("aria-pressed", String(active));
    });
  }

  function wireTagPills() {
    var accordion = document.getElementById("pagefind-site-tags");
    if (!accordion || accordion.dataset.wired) return;
    accordion.dataset.wired = "true";
    accordion.addEventListener("click", function (event) {
      var pill = event.target.closest(".search-tag-link");
      if (!pill) return;
      var cb = tagFilterCheckbox(pill.dataset.tag);
      if (cb) cb.click();
    });
  }

  // /search/ page: the shortcode renders a "Tags" accordion
  // (#pagefind-site-tags) after the search mount point with the same
  // content as the /tags/ taxonomy page.  Once PagefindUI builds its filter
  // drawer (fieldset.pagefind-ui__filter-panel) we move that accordion into
  // the panel, directly under the "Section" filter block, so it reads as a
  // second collapsible section.  Idempotent (skips when already in place).
  function positionSiteTagsPanel() {
    var tags = document.getElementById("pagefind-site-tags");
    if (!tags) return;
    var searchBox = document.querySelector(".search-box[data-site-search]");
    var panel =
      searchBox &&
      searchBox.querySelector(".pagefind-ui__filter-panel");

    if (panel && panel.getBoundingClientRect().height > 0) {
      // Panel is visible — move the accordion into it (under Section).
      if (tags.parentNode !== panel) {
        panel.appendChild(tags);
      }
    } else {
      // Panel not yet visible or hidden — keep accordion as a direct
      // child of the search-box, below the PagefindUI mount.
      if (searchBox && tags.parentNode !== searchBox) {
        searchBox.appendChild(tags);
      }
    }
  }

  // Modal results: #pagefind-ui exists statically on every page (search-modal
  // partial), but PagefindUI only mounts into it on first open.  Observing the
  // container itself catches the mount and every re-render.
  var modalResultsContainer = document.getElementById("pagefind-ui");
  if (modalResultsContainer) {
    observePagefindResults(modalResultsContainer);
  }

  // /search/ page: identical treatment.  search.js runs on every page; the
  // shortcode mounts PagefindUI into #pagefind-site-search independently.
  // Only watch when the shortcode's container ([data-site-search]) is present.
  var siteSearchContainer = document.getElementById("pagefind-site-search");
  if (siteSearchContainer) {
    observePagefindResults(siteSearchContainer);
  } else if (document.querySelector(".search-box[data-site-search]")) {
    var siteSearchObserver = new MutationObserver(function () {
      var container = document.getElementById("pagefind-site-search");
      if (container && container.querySelector(".pagefind-ui")) {
        siteSearchObserver.disconnect();
        observePagefindResults(container);
      }
    });
    siteSearchObserver.observe(document.body, { childList: true, subtree: true });
  }

  // Content pages: convert "Tags: #a #b" paragraphs into badges.  Script is
  // deferred so the DOM is ready; also run once the initial render settles.
  decorateTagParagraphs(document);
  wireTagPills();
  document.addEventListener("DOMContentLoaded", function () {
    decorateTagParagraphs(document);
  });
})();